{
  "id": "app-mvxwoco8",
  "name": "Plant Watering",
  "description": "Track each plant's watering schedule and get reminded at 9am",
  "theme": {
    "accent": "#2E7D32"
  },
  "capabilities": [
    "notifications"
  ],
  "data": {
    "plants": {
      "type": "list",
      "fields": {
        "id": "string",
        "name": "string",
        "interval": "number",
        "lastWatered": "date"
      }
    }
  },
  "state": {
    "newName": "",
    "newInterval": "7"
  },
  "schedule": {
    "waterDue": {
      "at": "09:00",
      "title": "Plants need water",
      "body": "{{plural(count(filter(plants, p => daysBetween(p.lastWatered, today()) >= p.interval)), 'plant needs', 'plants need')}} water today",
      "if": "count(filter(plants, p => daysBetween(p.lastWatered, today()) >= p.interval)) > 0",
      "open": "main",
      "sound": "@gentle"
    }
  },
  "start": "main",
  "screens": {
    "main": {
      "title": "My Plants",
      "scroll": true,
      "body": {
        "type": "column",
        "style": {
          "padding": 16,
          "gap": 12
        },
        "children": [
          {
            "type": "card",
            "children": [
              {
                "type": "column",
                "style": {
                  "align": "center",
                  "gap": 2,
                  "padding": 4
                },
                "children": [
                  {
                    "type": "text",
                    "variant": "headline",
                    "value": "Due today"
                  },
                  {
                    "type": "text",
                    "variant": "largeTitle",
                    "value": "{{count(filter(plants, p => daysBetween(p.lastWatered, today()) >= p.interval))}}"
                  },
                  {
                    "type": "text",
                    "variant": "callout",
                    "style": {
                      "color": "muted"
                    },
                    "value": "{{count(filter(plants, p => daysBetween(p.lastWatered, today()) >= p.interval)) > 0 ? plural(count(filter(plants, p => daysBetween(p.lastWatered, today()) >= p.interval)), 'plant needs', 'plants need') + ' water' : 'All watered 🎉'}}"
                  }
                ]
              }
            ]
          },
          {
            "type": "card",
            "children": [
              {
                "type": "column",
                "style": {
                  "gap": 8
                },
                "children": [
                  {
                    "type": "text",
                    "variant": "headline",
                    "value": "Add a plant"
                  },
                  {
                    "type": "row",
                    "style": {
                      "gap": 8,
                      "align": "center"
                    },
                    "children": [
                      {
                        "type": "textfield",
                        "placeholder": "Name (e.g. Monstera)",
                        "bind": "newName",
                        "style": {
                          "grow": 1
                        }
                      },
                      {
                        "type": "textfield",
                        "placeholder": "Days",
                        "bind": "newInterval",
                        "keyboard": "number",
                        "style": {
                          "width": 70
                        }
                      },
                      {
                        "type": "button",
                        "label": "Add",
                        "variant": "primary",
                        "onTap": {
                          "if": "trim(newName) != '' && num(newInterval) > 0",
                          "then": [
                            {
                              "push": "plants",
                              "value": {
                                "id": "uid()",
                                "name": "trim(newName)",
                                "interval": "num(newInterval)",
                                "lastWatered": "today()"
                              }
                            },
                            {
                              "set": "newName",
                              "to": "''"
                            },
                            {
                              "set": "newInterval",
                              "to": "'7'"
                            }
                          ]
                        }
                      }
                    ]
                  },
                  {
                    "type": "text",
                    "variant": "caption",
                    "style": {
                      "color": "muted"
                    },
                    "value": "How many days between waterings?"
                  }
                ]
              }
            ]
          },
          {
            "type": "text",
            "variant": "headline",
            "value": "{{len(plants) > 0 ? 'All plants (' + str(len(plants)) + ')' : 'All plants'}}"
          },
          {
            "type": "list",
            "items": "{{sort(plants, p => daysBetween(today(), addDays(p.lastWatered, p.interval)))}}",
            "as": "plant",
            "empty": "No plants yet — add your first above.",
            "swipe": [
              {
                "label": "Delete",
                "do": {
                  "remove": "plant"
                }
              }
            ],
            "row": {
              "type": "row",
              "style": {
                "gap": 8,
                "align": "center"
              },
              "children": [
                {
                  "type": "column",
                  "style": {
                    "grow": 1,
                    "gap": 2
                  },
                  "children": [
                    {
                      "type": "text",
                      "variant": "headline",
                      "value": "{{plant.name}}"
                    },
                    {
                      "type": "text",
                      "variant": "caption",
                      "style": {
                        "color": "muted"
                      },
                      "value": "{{'Every ' + plural(plant.interval, 'day') + ' · Last ' + formatDate(plant.lastWatered, 'MMM d') + ' · ' + (daysBetween(today(), addDays(plant.lastWatered, plant.interval)) <= 0 ? (daysBetween(today(), addDays(plant.lastWatered, plant.interval)) == 0 ? 'Due today' : plural(-daysBetween(today(), addDays(plant.lastWatered, plant.interval)), 'day') + ' overdue') : 'Due in ' + plural(daysBetween(today(), addDays(plant.lastWatered, plant.interval)), 'day'))}}"
                    }
                  ]
                },
                {
                  "type": "button",
                  "label": "{{daysBetween(plant.lastWatered, today()) >= plant.interval ? 'Water 💧' : 'Water'}}",
                  "variant": "{{daysBetween(plant.lastWatered, today()) >= plant.interval ? 'primary' : 'secondary'}}",
                  "onTap": {
                    "set": "plant.lastWatered",
                    "to": "today()"
                  }
                }
              ]
            }
          }
        ]
      }
    }
  }
}
